import re
docs = {
    1: "red socks on sale",
    2: "blue socks and green shoes",
    3: "red red socks for kids",
    4: "green hat",
}
# Build: term -> sorted postings list of doc ids
index = {}
for doc_id in sorted(docs):
    for term in set(re.findall(r"[a-z]+", docs[doc_id].lower())):
        index.setdefault(term, []).append(doc_id)
print("docs:", docs)
print("red  ->", index["red"])
print("socks->", index["socks"])

def intersect(a, b):
    # two-pointer merge on sorted lists: O(len(a) + len(b))
    i = j = 0
    out = []
    while i < len(a) and j < len(b):
        if a[i] == b[j]:
            out.append(a[i]); i += 1; j += 1
        elif a[i] < b[j]:
            i += 1
        else:
            j += 1
    return out

def search(query):
    lists = sorted((index.get(t, []) for t in query.split()), key=len)  # shortest first
    res = lists[0]
    for lst in lists[1:]:
        res = intersect(res, lst)
    return res

print("query 'red socks' ->", search("red socks"))
print("query 'red hat'   ->", search("red hat"))
